follows.follow_custom_js:
(function () {
  const card = document.getElementById('kaos-card');
  const type = document.getElementById('typeInner');
  const name = document.getElementById('alertMessageInner');
  const sub = document.getElementById('subInner');
  const nameWrap = document.getElementById('alertMessage');
  const subWrap = document.getElementById('alertSub');
  if (!card || !type || !name || !sub) return;

  function fitName() {
    const len = (name.textContent || '').trim().length;
    let size = 4.2;
    if (len > 14) size = Math.max(2.2, 4.2 - (len - 14) * (2.0 / 12));
    name.style.fontSize = size + 'vw';
  }

  const txt = (type.textContent || '').trim();
  type.textContent = '';
  [...txt].forEach(function (ch, i) {
    const s = document.createElement('span');
    s.textContent = ch === ' ' ? '\u00A0' : ch;
    type.appendChild(s);
    setTimeout(function () {
      s.style.opacity = '1';
      s.style.transform = 'translateY(0)';
    }, 220 + i * 35);
  });

  setTimeout(function () {
    fitName();
    nameWrap.style.opacity = '1';
    name.style.clipPath = 'polygon(0 0, 100% 0, 100% 100%, 0 100%)';
  }, 620);

  setTimeout(function () {
    subWrap.style.opacity = '1';
    subWrap.style.transform = 'translateY(0)';
  }, 980);

  setTimeout(function () {
    card.style.transition = 'opacity .4s ease';
    card.style.opacity = '0';
  }, 7200);
})();

follows.follow_custom_css:
@import url('https://fonts.googleapis.com/css2?family=Exo:ital,wght@0,600;0,700;0,900;1,700&display=swap');

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
}

body {
  font-family: 'Exo', sans-serif;
}

#kaos-card {
  position: absolute;
  left: 50%;
  bottom: 8vh;
  transform: translate(-50%, 0);
  width: 62.5vw;
  height: 20.833vw;
  opacity: 0;
  animation: cardIn .35s ease-out .05s forwards;
}

#alert-image {
  position: absolute !important;
  inset: 0 !important;
  z-index: 1 !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

#alert-image img {
  display: none !important;
}

#alert-image video {
  width: 100% !important;
  height: 100% !important;
  object-fit: contain !important;
  display: block !important;
}

#alert-type {
  position: absolute;
  left: 31.8%;
  top: 29.5%;
  z-index: 3;
  font-size: 1.7vw;
  font-weight: 700;
  letter-spacing: .18vw;
  color: var(--accent, #17DFF2);
  text-transform: uppercase;
  white-space: nowrap;
}

#alert-type > #typeInner {
  display: inline-block;
  opacity: 1;
  transform: none;
}

#typeInner > span {
  display: inline-block;
  opacity: 0;
  transform: translateY(.5vw);
  transition: opacity .18s ease, transform .18s ease;
}

#alertMessage {
  position: absolute;
  left: 31.8%;
  top: 41.5%;
  z-index: 4;
  width: 64%;
  height: 26%;
  overflow: hidden;
}

#alertMessageInner {
  display: block;
  width: 100%;
  font-size: 4.2vw;
  font-weight: 900;
  line-height: .95;
  color: var(--name, #EAF7F7);
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  clip-path: polygon(0 0, 0 0, 0 100%, 0 100%);
  transition: clip-path .55s cubic-bezier(.2, .8, .2, 1);
}

#alertSub {
  position: absolute;
  left: 31.8%;
  top: 69%;
  z-index: 3;
  font-size: 1.55vw;
  font-weight: 600;
  letter-spacing: .12vw;
  color: #9FB3B8;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  transform: translateY(.4vw);
  transition: opacity .35s ease, transform .35s ease;
}

@keyframes cardIn {
  from {
    opacity: 0;
    transform: translate(-50%, 1.2vw);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

